<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#1f2937;font-size:11px}h1{font-size:25px;margin:0}.header{display:table;width:100%;margin-bottom:28px}.header>div{display:table-cell;width:50%;vertical-align:top}.right{text-align:right}.muted{color:#6b7280}.party{display:table;width:100%;margin-bottom:24px}.party>div{display:table-cell;width:50%;vertical-align:top}table{width:100%;border-collapse:collapse}th,td{padding:8px;border-bottom:1px solid #d1d5db}th{background:#1f3a5f;color:white;text-align:left}.num{text-align:right}.totals{margin-left:auto;margin-top:18px;width:45%}.totals td{border:0;padding:4px 8px}.grand{font-size:14px;font-weight:bold;border-top:2px solid #1f3a5f!important}.footer{margin-top:32px;color:#6b7280;font-size:9px}</style></head><body>
<div class="header"><div><h1>{{ $invoice->document_type === 'credit_note' ? 'CREDIT NOTE' : 'INVOICE' }}</h1><div class="muted">{{ $invoice->invoice_number ?? 'DRAFT' }}</div></div><div class="right"><strong>{{ $invoice->seller_name ?: config('app.name') }}</strong><br>{{ $invoice->seller_address }}<br>{{ $invoice->seller_contact }}</div></div>
