<table><thead><tr><th>Description</th><th class="num">Qty</th><th class="num">Unit price</th><th class="num">Discount</th><th class="num">Tax</th><th class="num">Total</th></tr></thead><tbody>@foreach($invoice->items as $item)<tr><td>{{ $item->description }}</td><td class="num">{{ $item->quantity }}</td><td class="num">{{ number_format((float)$item->unit_price,4) }}</td><td class="num">{{ number_format((float)$item->discount_amount,4) }}</td><td class="num">{{ number_format((float)$item->tax_amount,4) }}</td><td class="num">{{ number_format((float)$item->line_total,4) }}</td></tr>@endforeach</tbody></table>
<table class="totals"><tr><td>Subtotal</td><td class="num">{{ number_format((float)$invoice->subtotal,4) }}</td></tr><tr><td>Discount</td><td class="num">-{{ number_format((float)$invoice->discount_total,4) }}</td></tr><tr><td>Tax</td><td class="num">{{ number_format((float)$invoice->tax_total,4) }}</td></tr><tr class="grand"><td>Total</td><td class="num">{{ $invoice->currency_code }} {{ number_format((float)$invoice->total,4) }}</td></tr><tr><td>Payments</td><td class="num">{{ number_format((float)$applied,4) }}</td></tr><tr><td>Balance</td><td class="num">{{ $invoice->currency_code }} {{ number_format((float)$balance,4) }}</td></tr></table>
